import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const aliasBlockStart = "# BEGIN GENERATED ASSET ALIASES";
export const aliasBlockEnd = "# END GENERATED ASSET ALIASES";

const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

export const apacheAssetAliases = (aliases) => [
  aliasBlockStart,
  "# Generated by node tools/asset-routing.mjs; edit tools/asset-aliases.json instead.",
  ...Object.entries(aliases).map(([legacy, canonical]) =>
    `RewriteRule ^${escapeRegex(legacy)}$ /${canonical} [R=301,L]`),
  aliasBlockEnd,
].join("\n");

export const vercelAssetAliases = (aliases) => Object.entries(aliases).map(([legacy, canonical]) => ({
  // Apache decodes paths before matching. Accept both forms on Vercel, where
  // old folder names containing a literal question mark arrive URL-encoded.
  source: "/" + legacy.replaceAll("?", ":question(\\?|%3[Ff])"),
  destination: "/" + canonical,
  permanent: true,
}));

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const aliases = JSON.parse(readFileSync(resolve(root, "tools/asset-aliases.json"), "utf8"));
  const htaccessPath = resolve(root, ".htaccess");
  const htaccess = readFileSync(htaccessPath, "utf8");
  const block = apacheAssetAliases(aliases);
  const start = htaccess.indexOf(aliasBlockStart);
  const end = htaccess.indexOf(aliasBlockEnd);
  if ((start === -1) !== (end === -1)) throw new Error("Incomplete asset alias block in .htaccess");
  writeFileSync(htaccessPath, start === -1
    ? htaccess.replace("RewriteEngine On", "RewriteEngine On\n\n" + block)
    : htaccess.slice(0, start) + block + htaccess.slice(end + aliasBlockEnd.length));
  const vercelPath = resolve(root, "vercel.json");
  const vercel = JSON.parse(readFileSync(vercelPath, "utf8"));
  // Keep redirects unrelated to asset compatibility intact.
  const otherRedirects = (vercel.redirects || []).filter(({ source }) =>
    !source.startsWith("/assets/") && !source.startsWith("/services/assets/"));
  vercel.redirects = [...vercelAssetAliases(aliases), ...otherRedirects];
  writeFileSync(vercelPath, JSON.stringify(vercel, null, 2) + "\n");
  console.log(`Generated ${Object.keys(aliases).length} asset redirects for Hostinger and Vercel.`);
}
